const item = $input.first();
const description = String(item.json?.task_description || '').trim();
const taskId = `mvp_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
const inputFiles = Object.entries(item.binary || {}).map(([field, file]) => ({
  field,
  filename: String(file.fileName || ''),
  mime_type: String(file.mimeType || ''),
}));
return [{
  json: {
    entrypoint: 'mvp_form',
    action: 'start',
    task_id: taskId,
    task_description: description,
    request_text: description,
    request: {
      objective: description,
      problem_statement: description,
      task_description: description,
      input_files: inputFiles,
    },
    context: {
      source: 'mvp-entry-form',
      submitted_task_id: taskId,
    },
    requested_by: 'mvp-form-engineer',
  },
  binary: item.binary || {},
}];

const response = $input.first().json || {};
const result = response.result && typeof response.result === 'object' ? response.result : null;
const deliverables = Array.isArray(result?.deliverables) ? result.deliverables : [];
const scheduleText = response.schedule_text
  || result?.release?.schedule_text
  || result?.compact_data?.generated_schedule
  || deliverables.find(value => typeof value?.schedule_text === 'string')?.schedule_text
  || null;
return [{json: {
  task_id: response.task_id || null,
  status: response.status || 'completed',
  message: response.message || (scheduleText ? 'SCHEDULE generated.' : 'MAS task completed.'),
  schedule_text: scheduleText,
  human_gate: response.human_gate || null,
  result: result || response,
}}];
